package ec.dmt.admin.school;
import jakarta.persistence.*;
@Entity @Table(name="parallel") public class SchoolParallel { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="course_id",nullable=false) private Course course; @Column(nullable=false) private String name; @Column(nullable=false) private boolean active=true; protected SchoolParallel(){} public SchoolParallel(Course course,String name,boolean active){this.course=course;this.name=name;this.active=active;} public Long getId(){return id;} public Course getCourse(){return course;} public String getName(){return name;} public boolean isActive(){return active;} public void update(Course course,String name,boolean active){this.course=course;this.name=name;this.active=active;} }
